import 'server-only'
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import { serverEnv } from '@/config/env.server'
import { hasEphemeralFilesystem } from '@/lib/db/data-dir'
import { logger } from '@/lib/logging/logger'
import type { Bucket, ImageStore } from './store'

/**
 * Images on the local filesystem. Development and tests only.
 *
 * Keys are generated by the server (`<owner uuid>/<uuid>/<size>.webp`), but are
 * still checked here so that nothing can ever resolve outside the media root.
 */

const SAFE_KEY = /^[a-z0-9-]+(\/[a-z0-9-]+)*(\.webp)?$/

export function resolveMediaRoot(configured: string): string {
  if (path.isAbsolute(configured)) return configured
  if (hasEphemeralFilesystem()) return path.join(os.tmpdir(), 'livinup', path.basename(configured))
  return path.resolve(/* turbopackIgnore: true */ process.cwd(), configured)
}

export class LocalImageStore implements ImageStore {
  readonly kind = 'local' as const
  private readonly root: string

  constructor(root = resolveMediaRoot(serverEnv().MEDIA_LOCAL_DIR)) {
    this.root = root
    if (serverEnv().NODE_ENV === 'production' && !hasEphemeralFilesystem()) {
      logger.warn('serving uploads from local disk in production; set SUPABASE_SECRET_KEY')
    }
  }

  private file(bucket: Bucket, key: string): string {
    if (!SAFE_KEY.test(key)) throw new Error('invalid media key')
    return path.join(this.root, bucket, ...key.split('/'))
  }

  async put(bucket: Bucket, key: string, body: Buffer): Promise<void> {
    const target = this.file(bucket, key)
    await mkdir(path.dirname(target), { recursive: true })
    await writeFile(target, body)
  }

  async get(bucket: Bucket, key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.file(bucket, key))
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
      throw error
    }
  }

  async remove(bucket: Bucket, keys: readonly string[]): Promise<void> {
    for (const key of keys) {
      await rm(this.file(bucket, key), { force: true })
    }
  }
}
